// Fetch all pending dates for this session
const input = $input.first().json.body || $input.first().json;
const personIds = input.person_ids || [];
const sessionId = input.session_id;

return {
  json: {
    session_id: sessionId,
    person_ids: personIds
  }
};

// For each pending date, fetch both profiles and trigger simulation
const dates = $input.all().map(item => item.json);
const flatDates = Array.isArray(dates[0]) ? dates[0] : dates;

return flatDates.map(date => ({
  json: {
    date_id: date.id,
    person_a_id: date.person_a_id,
    person_b_id: date.person_b_id
  }
}));
